void Maintenance::record_success(){
    auto value=snapshot();auto path=fs::path(control_directory)/"backup-history.json";json history={{"samples",json::array()}};
    if(fs::exists(path))history=read_json_object(path,"backup history",true);
    auto& samples=history["samples"];samples.push_back({{"source_bytes",value["estimate"]["source_bytes"]},{"backup_bytes",value["output_bytes"]},{"elapsed_seconds",std::max<int64_t>(1,value["elapsed_seconds"].get<int64_t>())},{"created_at",time(nullptr)},{"stage_seconds",value.value("stage_seconds",json::object())}});while(samples.size()>20)samples.erase(samples.begin());atomic_json(path,history);
}
