void configure_backup_visibility(httplib::Server& server,std::shared_ptr<Maintenance> state,std::shared_ptr<Authorization> auth){
    for(auto path:{"/backups/new","/backups/progress"})server.Get(path,[](const auto&,auto& res){res.set_content(backup_page,"text/html; charset=utf-8");});
    server.Get("/admin/backup-status",[state](const auto&,auto& res){try{response(res,200,state->snapshot());}catch(const std::exception&){response(res,503,{{"error","backup_status_unavailable"}});}});
    body_route(server,"POST","/admin/backup-estimate",[state](const auto& req,auto& res){try{
        auto type=req.get_header_value("Content-Type");if(type.substr(0,type.find(';'))!="application/json"){response(res,415,{{"error","unsupported_media_type"}});return;}
        auto p=json::parse(req.body,nullptr,false);if(!p.is_object())throw std::invalid_argument("invalid_packet");for(auto& item:p.items())if((item.key()!="mount"&&item.key()!="destination")||!item.value().is_string())throw std::invalid_argument("invalid_backup_location");
        if(state->requested||state->transfer_active){response(res,409,{{"error","maintenance_in_progress"}});return;}
        response(res,200,state->estimate(p.value("mount",std::string{}),p.value("destination",std::string{})));
    }catch(const std::invalid_argument& e){response(res,400,{{"error",e.what()}});}catch(const std::exception& e){response(res,503,{{"error",e.what()}});}},auth);
}
void run_maintenance_listener(const std::string& host,int port,std::shared_ptr<Maintenance> state,std::shared_ptr<Authorization> auth){
    httplib::Server server;server.new_task_queue=[] {return new httplib::ThreadPool(4);};server.set_read_timeout(5);server.set_write_timeout(5);server.set_payload_max_length(16384);
    server.set_default_headers({{"Cache-Control","no-store"},{"X-Content-Type-Options","nosniff"},{"X-Frame-Options","DENY"},{"Referrer-Policy","no-referrer"},{"Content-Security-Policy","default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'; object-src 'none'; base-uri 'none'; form-action 'self'"}});
    configure_browser_auth(server,auth);configure_backup_visibility(server,state,auth);
    server.Get("/",[](const auto&,auto& res){res.set_redirect("/backups/progress",303);});server.Get("/backups/explorer",[](const auto&,auto& res){res.set_redirect("/backups/progress",303);});
    server.Get("/admin/status",[state](const auto&,auto& res){auto p=state->snapshot();p["version"]=SPARK_VERSION;response(res,200,p);});
    server.set_pre_routing_handler([auth](const auto& req,auto& res){
        if(auth&&!browser_public_route(req)&&!auth->request(req,res)){if(res.status==401&&(req.method=="GET"||req.method=="HEAD")&&!req.has_header("Authorization")&&req.get_header_value("Accept").find("text/html")!=std::string::npos){res.body.clear();res.set_redirect("/login?next=/backups/progress",303);}return httplib::Server::HandlerResponse::Handled;}
        const bool read=req.method=="GET"||req.method=="HEAD";
        if(browser_public_route(req)||(read&&(req.path=="/"||req.path=="/backups/explorer"||req.path=="/backups/progress"||req.path=="/backups/new"||req.path=="/admin/status"||req.path=="/admin/backup-status")))return httplib::Server::HandlerResponse::Unhandled;
        res.set_header("Retry-After","5");res.set_header("Connection","close");response(res,503,{{"error","maintenance_in_progress"},{"status_url","/admin/backup-status"}});return httplib::Server::HandlerResponse::Handled;
    });
    if(!server.bind_to_port(host,port))throw std::runtime_error("Cannot bind backup status listener; backup was not started");
    std::exception_ptr error;std::thread executor([&]{server.wait_until_ready();try{state->execute();}catch(...){error=std::current_exception();}server.stop();});
    server.listen_after_bind();executor.join();if(error)std::rethrow_exception(error);
}
json backup_visibility_endpoints(){json out=json::array();for(auto path:{"/backups/new","/backups/progress","/admin/backup-status","/admin/backup-estimate"}){bool estimate=std::string(path)=="/admin/backup-estimate",status=std::string(path)=="/admin/backup-status";out.push_back({{"method",estimate?"POST":"GET"},{"path",path},{"description",estimate?"Preflight metadata estimate: per-drive logical/allocated bytes, approximate DB size, compressed-size range, free space and conservative reserve. Time range is null until a successful measured backup. Sources exclude backups and private control data. Estimates can change before start.":status?"Durable backup status: stage, elapsed time, process_alive, heartbeat_at, last_activity_at, output_bytes, verified_files, bounded log_tail and private log_path. Available during backup. Process liveness alone is not proof of progress. Unfinished jobs become interrupted on process restart.":"Authenticated backup estimate/confirmation or live progress page; progress remains available while ordinary REST returns 503 with Retry-After and TCP is paused."},{"input",{{"body",estimate?json{{"mount",""},{"destination",""}}:json(nullptr)}}},{"output",{{"status",200},{"body",estimate?json{{"duration_seconds",nullptr},{"space_sufficient",true},{"confidence","low; no measured backup history"}}:status?json{{"state","running"},{"stage","compression"},{"process_alive",true},{"output_bytes",12345}}:json("HTML")}}}});}return out;}
